pid_t pid = fork();
if (pid < 0) { perror("fork"); exit(1); }
if (pid == 0) {                              // child
    execlp("ls", "ls", "-l", (char *)NULL);
    perror("exec");                          // only runs if exec failed
    _exit(127);                              // skip the stdio buffers and atexit
}                                            // handlers copied from the parent
int status;
waitpid(pid, &status, 0);                    // parent: sleep until the child ends
if (WIFEXITED(status))
    printf("exit code %d\n", WEXITSTATUS(status));
else if (WIFSIGNALED(status))
    printf("signal %d, bash shows %d\n", WTERMSIG(status), 128 + WTERMSIG(status));
